WITH car AS (SELECT REPLACE(id_imovel,'-','') id_car_norm,area FROM `basedosdados.br_sfb_sicar.area_imovel` WHERE data_extracao>=DATE '2026-06-02' AND data_extracao<=DATE '2026-08-04' QUALIFY ROW_NUMBER() OVER(PARTITION BY REPLACE(id_imovel,'-','') ORDER BY data_extracao DESC)=1),pl AS (SELECT DISTINCT id_referencia_bacen,numero_ordem,REPLACE(id_car,'-','') id_car_norm FROM `basedosdados.br_bcb_sicor.recurso_publico_propriedade` WHERE ano_emissao=2023 AND id_car IS NOT NULL AND TRIM(id_car)!=''),n AS (SELECT id_referencia_bacen,numero_ordem,COUNT(*) n_imoveis FROM pl GROUP BY 1,2),pc AS (SELECT c.id_car_norm,c.area,SUM(op.area_financiada/n.n_imoveis) area_financiada FROM `basedosdados.br_bcb_sicor.operacao` op JOIN n USING(id_referencia_bacen,numero_ordem) JOIN pl USING(id_referencia_bacen,numero_ordem) JOIN car c USING(id_car_norm) WHERE op.ano_emissao=2023 GROUP BY 1,2),dprog AS (SELECT DISTINCT chave,valor FROM `basedosdados.br_bcb_sicor.dicionario` WHERE nome_coluna='id_programa'),dfonte AS (SELECT DISTINCT chave,valor FROM `basedosdados.br_bcb_sicor.dicionario` WHERE nome_coluna='id_fonte_recurso'),x AS (SELECT op.id_programa,op.id_fonte_recurso,op.valor_parcela_credito/n.n_imoveis credito,op.area_financiada/n.n_imoveis area_financiada FROM `basedosdados.br_bcb_sicor.operacao` op JOIN n USING(id_referencia_bacen,numero_ordem) JOIN pl USING(id_referencia_bacen,numero_ordem) JOIN pc USING(id_car_norm) WHERE op.ano_emissao=2023 AND pc.area_financiada>pc.area)
SELECT COALESCE(p.valor,CONCAT('código ',x.id_programa)) programa,COALESCE(f.valor,CONCAT('código ',x.id_fonte_recurso)) fonte_recurso,SUM(credito) credito,SUM(area_financiada) area_financiada,COUNT(*) linhas
FROM x LEFT JOIN dprog p ON p.chave=x.id_programa LEFT JOIN dfonte f ON f.chave=x.id_fonte_recurso
GROUP BY programa,fonte_recurso ORDER BY credito DESC LIMIT 30